+                var taxData = taxResp.Code == 200 && taxResp.Result != null ? taxResp.Result.Where(x => x.project == "小计").ToList() : new List<TaxReportMonthRangeResponse>();
+
+                foreach (var month in months)
+                {
+                    var taxMonthKey = month.Replace("-", ".");
