+        /// <param name="endTime">结束日期</param>
+        /// <returns>月份数</returns>
+        private static int GetMonthsCount(DateTime beginTime, DateTime endTime)
+        {
+            return ((endTime.Year - beginTime.Year) * 12) + endTime.Month - beginTime.Month + 1;
