+            public double TotalSeconds { get; set; }
+            /// <summary>
+            /// 规则定义ID列表
+            /// </summary>
+            public List<int> RuleDefinitionIds { get; set; }
+            /// <summary>
+            /// 错误信息列表
+            /// </summary>
+            public List<string> Errors { get; set; } = new List<string>();
