+        private async Task<SharedDataCache> PreloadSharedData(List<ORDR> orders)
+        {
+            var orderIds = orders.Select(o => o.DocEntry).ToList();
+            var cache = new SharedDataCache();
+
+            // 1. 加载所有业务员信息
+            cache.SlpNames = await UnitWork.Find<OSLP>(null).ToDictionaryAsync(x => x.SlpCode, x => x.SlpName);
+
+            // 2. 加载所有客户类型信息
+            var customerTypesList = await _customerCommonApp.GetMainlandCustomerType();
+            cache.CustomerTypes = customerTypesList.ToDictionary(ct => ct.CardCode, ct => ct);
+
+            // 3. 批量加载开票信息
+            cache.OrderInvoices = await LoadInvoicesAsync(orderIds);
+
+            // 4. 批量加载收款信息
+            var receiptDict = new Dictionary<int, List<ReceiptForOrder>>();
+
+            // 先加载直接收款的 ORCT（暂存，后续统一计算 AppliedAmount）
+            // 分批查询，避免 SQL IN 子句超过参数上限
+            var directReceiptsList = new List<ORCT>();
+            const int orctBatchSize = 1000;
+            for (int i = 0; i < orderIds.Count; i += orctBatchSize)
+            {
+                var batchIds = orderIds.Skip(i).Take(orctBatchSize).ToList();
+                var batchResult = await UnitWork.Find<ORCT>(r => r.U_XSDD.HasValue && batchIds.Contains(r.U_XSDD.Value) && r.Canceled != "Y")
+                    .ToListAsync();
+                directReceiptsList.AddRange(batchResult);
