+                    if (!indirectReceiptsDict.TryGetValue(rctDocNum, out var receipt))
+                        continue;
+
+                    var matchingRct2 = relatedRct2.Where(r => r.DocNum == rctDocNum).ToList();
+                    var appliedAmount = matchingRct2.Sum(r => r.SumApplied);
+                    var appliedAmountFC = matchingRct2.Sum(r => r.AppliedFC);
+
+                    if (!receiptDict.ContainsKey(orderId))
+                        receiptDict[orderId] = new List<ReceiptForOrder>();
+                    receiptDict[orderId].Add(new ReceiptForOrder
+                    {
+                        DocEntry = receipt.DocEntry,
+                        DocNum = receipt.DocNum,
+                        DocDate = receipt.DocDate,
+                        Canceled = receipt.Canceled,
+                        AppliedAmount = appliedAmount,
+                        AppliedAmountFC = appliedAmountFC
+                    });
+                }
+            }
+
+            // 处理直接收款（U_XSDD有值）：直接使用 ORCT.DocTotal 作为该订单的收款金额
+            // 原因：部分收款走日记帐科目而非发票核销，RCT2.SumApplied 无法反映完整金额
+            foreach (var orderId in orderIds)
+            {
+                if (!directReceiptsByOrder.TryGetValue(orderId, out var orderDirectReceipts))
+                    continue;
+
+                foreach (var receipt in orderDirectReceipts)
+                {
+                    if (!receiptDict.ContainsKey(orderId))
+                        receiptDict[orderId] = new List<ReceiptForOrder>();
+                    receiptDict[orderId].Add(new ReceiptForOrder
+                    {
+                        DocEntry = receipt.DocEntry,
+                        DocNum = receipt.DocNum,
+                        DocDate = receipt.DocDate,
+                        Canceled = receipt.Canceled,
+                        AppliedAmount = receipt.DocTotal ?? 0M,
+                        AppliedAmountFC = receipt.DocTotalFC ?? 0M
+                    });
+                }
+            }
+
+            // 对每个订单的收款按日期排序并去重（合并同一 DocEntry 的金额）
+            var orderIdsToUpdate = receiptDict.Keys.ToList();
+            foreach (var orderId in orderIdsToUpdate)
+            {
+                receiptDict[orderId] = receiptDict[orderId]
+                    .GroupBy(r => r.DocEntry)
+                    .Select(g => new ReceiptForOrder
+                    {
+                        DocEntry = g.Key,
+                        DocNum = g.First().DocNum,
+                        DocDate = g.First().DocDate,
+                        Canceled = g.First().Canceled,
+                        AppliedAmount = g.Sum(r => r.AppliedAmount),
+                        AppliedAmountFC = g.Sum(r => r.AppliedAmountFC)
+                    })
+                    .OrderBy(r => r.DocDate)
+                    .ToList();
+            }
+            cache.OrderReceipts = receiptDict;
+
+            // 6. 批量加载SaleOrderPlugin
+            cache.SaleOrderPlugins = await UnitWork.Find<SaleOrderPlugin>(sp => orderIds.Contains(sp.DocEntry) && sp.SboId == SboIdEnums.neware_201304)
+                .ToDictionaryAsync(sp => sp.DocEntry, sp => sp);
+
+            // 7. 批量加载PenaltyEvent
+            var orderIdsStr = orderIds.Select(id => id.ToString()).ToList();
+            var penaltyEventsList = await UnitWork.Find<PenaltyEvent>(pe => orderIdsStr.Contains(pe.TriggerDocEntry) && pe.TriggerDocType == "ORDR" && (pe.RuleDefinitionId == 9 || pe.RuleDefinitionId == 10))
+                .OrderBy(pe => pe.PenaltyStartDate)
+                .ToListAsync();
+            cache.OrderPenaltyEvents = penaltyEventsList.GroupBy(pe => int.Parse(pe.TriggerDocEntry))
+                .ToDictionary(g => g.Key, g => g.ToList());
+
+            // 8. 加载规则定义
+            cache.SchoolRule = await UnitWork.Find<PenaltyRuleDefinition>(r => r.RuleHandlerCode == "HANDLER_OVERDUE_AFTER_BILL" && r.IsActive && r.Param_String2 == "School").FirstOrDefaultAsync();
+            cache.OtherRule = await UnitWork.Find<PenaltyRuleDefinition>(r => r.RuleHandlerCode == "HANDLER_OVERDUE_AFTER_BILL" && r.IsActive && r.Param_String2 == "Other").FirstOrDefaultAsync();
+
+            // 10. 加载可清备注（【可清单】和不可清单）
+            var batchSaleOrderRemarkCanClear = await UnitWork.Find<SaleOrdrRemark>(r =>
+                orderIds.Contains(r.DocEntry) &&
+                r.SboId == SboIdEnums.neware_201304 &&
+                r.Remark.Contains("【可清单】"))
+                .ToListAsync();
+
+            var batchSaleOrderRemarkCannotClear = await UnitWork.Find<SaleOrdrRemark>(r =>
+                orderIds.Contains(r.DocEntry) &&
+                r.SboId == SboIdEnums.neware_201304 &&
+                r.Remark.Contains("不可清单"))
+                .ToListAsync();
+
+            // 判断是否应该截止计算：只有当【可清单】比不可清单晚时才截止
+            cache.CanClearCutOffDates = new Dictionary<int, DateTime?>();
+            var canClearDict = batchSaleOrderRemarkCanClear.GroupBy(x => x.DocEntry).ToDictionary(g => g.Key, g => g.OrderByDescending(x => x.CreateDate).First());
+            var cannotClearDict = batchSaleOrderRemarkCannotClear.GroupBy(x => x.DocEntry).ToDictionary(g => g.Key, g => g.OrderByDescending(x => x.CreateDate).First());
+
+            foreach (var orderId in orderIds)
+            {
+                var hasCanClear = canClearDict.TryGetValue(orderId, out var canClearRemark);
+                var hasCannotClear = cannotClearDict.TryGetValue(orderId, out var cannotClearRemark);
